import math
import os
import secrets

from contextlib import asynccontextmanager
from datetime import datetime, timezone
from typing import Annotated

import psycopg
from psycopg.rows import dict_row

from fastapi import FastAPI, Depends, Header, HTTPException
from pydantic import BaseModel, ConfigDict, Field


# =====================================================
# CONFIGURACIÓN
# =====================================================

API_KEY = os.environ.get("MAPA_API_KEY")

if not API_KEY:
    raise RuntimeError("Debes definir MAPA_API_KEY")

if not os.environ.get("PGPASSWORD"):
    raise RuntimeError("Debes definir PGPASSWORD")


def abrir_db():
    """
    Psycopg lee estas variables del entorno:
    PGHOST, PGPORT, PGDATABASE, PGUSER y PGPASSWORD.
    """
    return psycopg.connect(
        connect_timeout=5,
        row_factory=dict_row
    )


# =====================================================
# SEGURIDAD
# =====================================================

def verificar_clave(
    x_api_key: Annotated[str | None, Header()] = None
):
    if not secrets.compare_digest(x_api_key or "", API_KEY):
        raise HTTPException(
            status_code=401,
            detail="Clave API incorrecta"
        )


# =====================================================
# CREACIÓN DE TABLAS
# =====================================================

@asynccontextmanager
async def lifespan(app: FastAPI):
    with abrir_db() as db:
        db.execute("""
            CREATE TABLE IF NOT EXISTS nodos (
                id BIGINT GENERATED BY DEFAULT AS IDENTITY
                    PRIMARY KEY,

                latitud DOUBLE PRECISION NOT NULL
                    CHECK (latitud BETWEEN -90 AND 90),

                longitud DOUBLE PRECISION NOT NULL
                    CHECK (longitud BETWEEN -180 AND 180),

                nombre VARCHAR(80) NOT NULL,
                tipo VARCHAR(32) NOT NULL,
                descripcion VARCHAR(200) NOT NULL,

                recibido_utc TIMESTAMPTZ NOT NULL
            )
        """)

        db.execute("""
            CREATE TABLE IF NOT EXISTS aristas (
                origen BIGINT NOT NULL
                    REFERENCES nodos(id),

                destino BIGINT NOT NULL
                    REFERENCES nodos(id),

                distancia_m DOUBLE PRECISION NOT NULL
                    CHECK (distancia_m >= 0),

                PRIMARY KEY (origen, destino),

                CHECK (origen < destino)
            )
        """)

    # El contexto confirma los cambios y cierra la conexión.
    yield


app = FastAPI(
    title="API de mapa peatonal",
    version="2.0",
    lifespan=lifespan,
    dependencies=[Depends(verificar_clave)]
)


# =====================================================
# MODELOS
# =====================================================

class Lugar(BaseModel):
    nombre: str = Field(
        default="Sin asignar",
        min_length=1,
        max_length=80
    )

    tipo: str = Field(
        default="punto",
        min_length=1,
        max_length=32
    )

    descripcion: str = Field(
        default="",
        max_length=200
    )


class NodoNuevo(Lugar):
    model_config = ConfigDict(allow_inf_nan=False)

    latitud: float = Field(ge=-90, le=90)
    longitud: float = Field(ge=-180, le=180)

    conectar_con: int | None = Field(default=None, ge=1)


class ConexionNueva(BaseModel):
    origen: int = Field(ge=1)
    destino: int = Field(ge=1)


# =====================================================
# DISTANCIAS Y CONSULTAS
# =====================================================

def distancia_metros(lat1, lon1, lat2, lon2):
    radio = 6371000.0

    phi1 = math.radians(lat1)
    phi2 = math.radians(lat2)

    dlat = phi2 - phi1
    dlon = math.radians(lon2 - lon1)

    a = (
        math.sin(dlat / 2) ** 2
        + math.cos(phi1)
        * math.cos(phi2)
        * math.sin(dlon / 2) ** 2
    )

    a = max(0.0, min(1.0, a))

    return 2 * radio * math.atan2(
        math.sqrt(a),
        math.sqrt(1 - a)
    )


def obtener_nodo(db, nodo_id):
    nodo = db.execute(
        "SELECT * FROM nodos WHERE id = %s",
        (nodo_id,)
    ).fetchone()

    if nodo is None:
        raise HTTPException(
            status_code=404,
            detail=f"No existe el nodo {nodo_id}"
        )

    return nodo


def conectar_nodos(db, origen, destino):
    if origen == destino:
        raise HTTPException(
            status_code=400,
            detail="No puedes conectar un nodo consigo mismo"
        )

    a = obtener_nodo(db, origen)
    b = obtener_nodo(db, destino)

    distancia = distancia_metros(
        a["latitud"],
        a["longitud"],
        b["latitud"],
        b["longitud"]
    )

    # Conexión no dirigida: una sola fila por pareja.
    origen, destino = sorted((origen, destino))

    db.execute("""
        INSERT INTO aristas (
            origen,
            destino,
            distancia_m
        )
        VALUES (%s, %s, %s)

        ON CONFLICT (origen, destino)
        DO UPDATE SET
            distancia_m = EXCLUDED.distancia_m
    """, (origen, destino, distancia))

    return {
        "origen": origen,
        "destino": destino,
        "distancia_m": distancia
    }


# =====================================================
# ENDPOINTS
# =====================================================

@app.post("/nodos", status_code=201)
def crear_nodo(datos: NodoNuevo):
    recibido = datetime.now(timezone.utc)

    with abrir_db() as db:
        nodo = db.execute("""
            INSERT INTO nodos (
                latitud,
                longitud,
                nombre,
                tipo,
                descripcion,
                recibido_utc
            )
            VALUES (%s, %s, %s, %s, %s, %s)
            RETURNING *
        """, (
            datos.latitud,
            datos.longitud,
            datos.nombre,
            datos.tipo,
            datos.descripcion,
            recibido
        )).fetchone()

        conexion = None

        if datos.conectar_con is not None:
            conexion = conectar_nodos(
                db,
                datos.conectar_con,
                nodo["id"]
            )

    # Si alguna operación falla, el contexto revierte
    # toda la transacción, incluida la creación del nodo.
    return {
        "nodo": nodo,
        "conexion": conexion
    }


@app.get("/nodos")
def listar_nodos():
    with abrir_db() as db:
        nodos = db.execute("""
            SELECT *
            FROM nodos
            ORDER BY id
        """).fetchall()

    return nodos


@app.put("/nodos/{nodo_id}/lugar")
def asignar_lugar(nodo_id: int, datos: Lugar):
    with abrir_db() as db:
        nodo = db.execute("""
            UPDATE nodos
            SET nombre = %s,
                tipo = %s,
                descripcion = %s
            WHERE id = %s
            RETURNING *
        """, (
            datos.nombre,
            datos.tipo,
            datos.descripcion,
            nodo_id
        )).fetchone()

        if nodo is None:
            raise HTTPException(
                status_code=404,
                detail=f"No existe el nodo {nodo_id}"
            )

    return nodo


@app.post("/aristas")
def crear_conexion(datos: ConexionNueva):
    with abrir_db() as db:
        resultado = conectar_nodos(
            db,
            datos.origen,
            datos.destino
        )

    return resultado


@app.get("/mapa")
def exportar_mapa():
    with abrir_db() as db:
        # Ambas consultas ven la misma versión del mapa.
        db.execute(
            "SET TRANSACTION ISOLATION LEVEL REPEATABLE READ"
        )

        filas_nodos = db.execute("""
            SELECT *
            FROM nodos
            ORDER BY id
        """).fetchall()

        filas_aristas = db.execute("""
            SELECT *
            FROM aristas
            ORDER BY origen, destino
        """).fetchall()

    nodos = {}

    for fila in filas_nodos:
        nodos[fila["id"]] = {
            "id": fila["id"],
            "gps": {
                "latitud": fila["latitud"],
                "longitud": fila["longitud"]
            },
            "lugar": {
                "nombre": fila["nombre"],
                "tipo": fila["tipo"],
                "descripcion": fila["descripcion"]
            },
            "recibido_utc": fila["recibido_utc"],
            "vecinos": []
        }

    for fila in filas_aristas:
        origen = fila["origen"]
        destino = fila["destino"]
        peso = fila["distancia_m"]

        nodos[origen]["vecinos"].append({
            "id": destino,
            "peso_m": peso
        })

        nodos[destino]["vecinos"].append({
            "id": origen,
            "peso_m": peso
        })

    return {
        "version": 1,
        "unidad_peso": "metros",
        "grafo_dirigido": False,
        "nodos": list(nodos.values())
    }